	array(
		'question_text'  => 'A client rarely makes direct eye contact during sessions. The therapist interprets this as evidence that the client is resistant and dishonest.What is the most appropriate response?',
		'option_a'       => 'Document resistance and dishonesty because both are observable facts',
		'option_b'       => 'Explore what eye contact means to the client and consider cultural, personal, trauma-related, and other explanations before reaching a clinical conclusion',
