	array(
		'question_text'  => 'A therapist is unsure whether a client’s spiritual practice is culturally meaningful, clinically concerning, or both. The therapist plans to consult a specialist but has not discussed the practice with the client.What is the strongest response?',
		'option_a'       => 'Consult the specialist and avoid asking the client because the client may provide biased information',
