	array(
		'question_text'  => 'A therapist lacks experience with a client’s cultural and spiritual traditions. The therapist can obtain consultation and education promptly, the client wishes to continue treatment, and no immediate risk is present.What is the most appropriate response?',
		'option_a'       => 'Refer immediately because clinicians should treat only clients who share their cultural background',
