	array(
		'question_text'  => 'A client explains that important decisions are traditionally discussed with close family members and asks that two relatives participate in treatment planning.What is the most appropriate response?',
		'option_a'       => 'Refuse because client autonomy always requires independent decision-making',
		'option_b'       => 'Clarify the client’s wishes, obtain appropriate permission, define each person’s role, address confidentiality, and monitor whether the involvement remains helpful and voluntary',
