	array(
		'question_text'  => 'A client repeatedly tells the therapist that a treatment recommendation conflicts with important cultural and spiritual practices. The therapist refuses to explore the concern, describes the client as resistant, and continues the same approach despite worsening distress.Which analysis is most accurate?',
		'option_a'       => 'No ethical concern exists because therapists may choose any treatment approach they prefer',
